/* 1) 软清空: 保留相机/光源, 只清模型 */
ssp.sceneTool.clear(true);

/* 2) 硬清空: 连相机/光源也清 (场景会变黑) */
ssp.sceneTool.clear(false);

/* 3) 切换场景: clear + loadSubcategory */
ssp.sceneTool.clear();
const infos = await ssp.modelTool.loadSubcategory('hospital');
console.log('loaded', infos.length, 'GLB');`,a7=["默认 keepCameraLight=true, 避免黑屏","清完后对象仍可访问, 但已 dispose, 不能 add 回场景","切场景: clear + loadSubcategory, 不要只 clear 不加载"],l7=["scene","clear","reset"],c7={id:K9,category:Y9,subcategory:Z9,intent:J9,scene:Q9,sdk:e7,method:t7,signature:n7,params:s7,returns:i7,code:o7,example:r7,guard:a7,tags:l7},d7="dispose",u7="scene",h7="root",f7=["销毁 GPU 资源","dispose","释放 GPU 资源","释放 mesh","释放材质","释放几何"],p7="3D",m7="ssp-shim",g7="ssp.sceneTool.dispose",y7="dispose(): void",_7=[],b7="void",v7="ssp.sceneTool.dispose();",T7=`/* 释放场景中所有 mesh 的 GPU 资源 (geometry / material) */
