/* 不要在 clear 前 dispose, 否则对象还在 scene 但 GPU 资源已释放 */`,A7=["只释放 GPU 资源 (geometry/material), 不清空场景对象, 不影响 window.ssp","不可逆: 调完后 mesh 无法渲染, 必须清掉 scene","切场景: dispose → clear → loadSubcategory","多次调用安全 (重复 dispose 已经被 dispose 的资源会 warning)"],S7=["clear"],x7=["destroy","lifecycle","gpu"],E7={id:d7,category:u7,subcategory:h7,intent:f7,scene:p7,sdk:m7,method:g7,signature:y7,params:_7,returns:b7,code:v7,example:T7,guard:A7,seeAlso:S7,tags:x7},w7="help",I7="scene",M7="help",C7=["帮助","你能做什么","怎么使用 AI 场景助手"],R7="template.help",P7="help(): TemplateResult",L7=!0,D7=[],O7="{ message }",N7="return { message: '可查询、统计、高亮、聚焦、隐藏或隔离场景对象，也可控制主视角和楼层炸开。' };",F7="return { message: '显示帮助' };",k7=["该模板不访问 SSP，只返回能力说明"],U7=["ai","help"],B7={id:w7,category:I7,subcategory:M7,intent:C7,method:R7,signature:P7,aiEnabled:L7,params:D7,returns:O7,code:N7,example:F7,guard:k7,tags:U7},z7="setBackgroundColor",$7="scene",V7="root",G7=["设置背景颜色","改背景","换底色","天空背景","change bg","bg color"],H7="3D",j7="ssp-shim",W7="ssp.sceneTool.setBackgroundColor",q7="setBackgroundColor(color: string | number): void",X7=[{name:"color",type:"string | number",required:!0,desc:"颜色 — hex 字符串 ('#000033') / CSS 名 ('black') / 0xRRGGBB 数字",examples:["'#0a0a1a'","'#87ceeb' (sky blue)","0x101218"]}],K7="void",Y7="ssp.sceneTool.setBackgroundColor('#0a0a1a');",Z7=`/* 几种常见背景 */

/* 深色 (默认风格) */
ssp.sceneTool.setBackgroundColor('#0a0a1a');

/* 蓝天 (白天建筑可视化) */
ssp.sceneTool.setBackgroundColor('#87ceeb');

/* 黑色 (拍电影感) */
ssp.sceneTool.setBackgroundColor(0x000000);

/* 配合雾化看深度 */
ssp.sceneTool.setBackgroundColor('#0a0a1a');
ssp.sceneTool.setFog({ color: '#0a0a1a', near: 100, far: 500 });`,J7=["颜色立即生效, 不带 transition","要淡入淡出请自己用 tween 工具 (ssp.animationTool.addTween 暂未实现)","深色背景建议同时设雾色一致, 避免边缘突兀"],Q7=["setFog"],eW=["background","color","sky"],tW={id:z7,category:$7,subcategory:V7,intent:G7,scene:H7,sdk:j7,method:W7,signature:q7,params:X7,returns:K7,code:Y7,example:Z7,guard:J7,seeAlso:Q7,tags:eW},nW="setFog",sW="scene",iW="root",oW=["设置雾效","雾化","fog"],rW="3D",aW="ssp-shim",lW="ssp.sceneTool.setFog",cW="setFog(options?: { color?, near?, far?, visible? }): void",dW=[{name:"options",type:"{ color?: IColor, near?: number, far?: number, visible?: boolean }",required:!1}],uW="void",hW="ssp.sceneTool.setFog({ color: '#aaccff', near: 100, far: 800, visible: true });",fW="ssp.sceneTool.setFog({ color: 0xcce0ff, near: 200, far: 1200, visible: true });",pW=["不传则使用 SceneMetadata.json 中的 fog 配置"],mW=["setBackgroundColor"],gW=["fog","atmosphere"],yW={id:nW,category:sW,subcategory:iW,intent:oW,scene:rW,sdk:aW,method:lW,signature:cW,params:dW,returns:uW,code:hW,example:fW,guard:pW,seeAlso:mW,tags:gW},_W="update",bW="scene",vW="root",TW=["刷新场景","强制重渲染","render update","触发 camera-controls 重算"],AW="3D",SW="ssp-shim",xW="ssp.sceneTool.update",EW="update(): void",wW=[],IW="void",MW="ssp.sceneTool.update();",CW=`/* 实际上 Three.js renderer 在每帧 RAF 自动渲染, sceneTool.update() 是 noop 占位 */

